21	// Portable popcount
22	inline int popcount(Mask m)
23	{
24	#if defined(_MSC_VER)
25	    return __popcnt(static_cast<unsigned int>(m));
26	#else
27	    return __builtin_popcount(static_cast<unsigned int>(m));
28	#endif
29	}
