31	// Portable count trailing zeros (input must be non-zero)
32	inline int ctz(Mask m)
33	{
34	#if defined(_MSC_VER)
35	    unsigned long index;
36	    _BitScanForward(&index, static_cast<unsigned long>(m));
37	    return static_cast<int>(index);
38	#else
39	    return __builtin_ctz(static_cast<unsigned int>(m));
40	#endif
41	}
