43	#if SUDOKU_AVX2
44	// AVX2-optimized namespace for vectorized operations
45	namespace SudokuAVX2
46	{
47	    // 16 x 16-bit lanes in a 256-bit register
48	    static constexpr int LANES = 16;
49	    static constexpr Mask ALL_DIGITS = 0x3FE; // bits 1-9 set
50	
51	    // Broadcast a 16-bit mask to all 16 lanes
52	    inline __m256i broadcast_mask(Mask m)
53	    {
54	        return _mm256_set1_epi16(static_cast<short>(m));
55	    }
56	
57	    // Load 16 cell candidates (unaligned, 16 * 2 = 32 bytes)
58	    inline __m256i load_candidates(const Mask* ptr)
59	    {
60	        return _mm256_loadu_si256(reinterpret_cast<const __m256i*>(ptr));
61	    }
62	
63	    // Store 16 cell candidates
64	    inline void store_candidates(Mask* ptr, __m256i val)
65	    {
66	        _mm256_storeu_si256(reinterpret_cast<__m256i*>(ptr), val);
67	    }
68	
69	    // Vectorized popcount for 16 x 16-bit values using nibble lookup table
70	    // Returns popcount for each 16-bit lane in lower 8 bits of each 16-bit lane
71	    inline __m256i popcount_epi16(__m256i x)
72	    {
73	        // Split each 16-bit lane into 4 nibbles (4 bits each)
74	        // Use 16-entry lookup table (popcount for 0-15) duplicated across 256-bit lanes
75	        const __m256i popcnt_lut = _mm256_setr_epi8(
76	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4,  // lane 0: popcount for 0-15
77	            0,1,1,2,1,2,2,3,1,2,2,3,2,3,3,4   // lane 1: same (shuffle operates per 128-bit lane)
78	        );
79	
80	        // Extract low nibbles of each byte
81	        __m256i nibble_mask = _mm256_set1_epi8(0x0F);
82	        __m256i lo_nibble = _mm256_and_si256(x, nibble_mask);
83	        __m256i hi_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 4), nibble_mask);
84	        __m256i lo2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 8), nibble_mask);
85	        __m256i hi2_nibble = _mm256_and_si256(_mm256_srli_epi16(x, 12), nibble_mask);
86	
87	        // Lookup popcount for each nibble
88	        __m256i cnt0 = _mm256_shuffle_epi8(popcnt_lut, lo_nibble);
89	        __m256i cnt1 = _mm256_shuffle_epi8(popcnt_lut, hi_nibble);
90	        __m256i cnt2 = _mm256_shuffle_epi8(popcnt_lut, lo2_nibble);
91	        __m256i cnt3 = _mm256_shuffle_epi8(popcnt_lut, hi2_nibble);
92	
93	        // Sum all 4 nibbles per 16-bit lane
94	        __m256i sum = _mm256_add_epi8(cnt0, cnt1);
95	        sum = _mm256_add_epi8(sum, cnt2);
96	        sum = _mm256_add_epi8(sum, cnt3);
97	
98	        return sum;
99	    }
100	
101	    // Check which lanes have exactly 1 candidate (naked singles)
102	    // Returns mask where each 16-bit lane is 0xFFFF if exactly 1 bit set, 0 otherwise
103	    inline __m256i naked_singles_mask(__m256i candidates)
104	    {
105	        // (candidates & (candidates - 1)) == 0 && candidates != 0
106	        __m256i dec = _mm256_sub_epi16(candidates, _mm256_set1_epi16(1));
107	        __m256i and_result = _mm256_and_si256(candidates, dec);
108	        __m256i is_zero = _mm256_cmpeq_epi16(and_result, _mm256_setzero_si256());
109	        __m256i non_zero = _mm256_cmpgt_epi16(candidates, _mm256_setzero_si256());
110	        return _mm256_and_si256(is_zero, non_zero);
111	    }
112	
113	    // Clear a specific digit mask from all candidates (vectorized)
114	    // candidates &= ~mask
115	    inline __m256i clear_digit(__m256i candidates, Mask digit_mask)
116	    {
117	        __m256i mask = broadcast_mask(~digit_mask);
118	        return _mm256_and_si256(candidates, mask);
119	    }
120	
121	    // Compute candidates for 16 cells with same row/col/box (rare case)
122	    // More commonly: compute for cells in same row (different cols, same row mask)
123	    inline __m256i compute_candidates_row(__m256i row_mask, __m256i col_masks, __m256i box_masks)
124	    {
125	        __m256i combined = _mm256_or_si256(_mm256_or_si256(row_mask, col_masks), box_masks);
126	        __m256i all_digits = broadcast_mask(ALL_DIGITS);
127	        return _mm256_andnot_si256(combined, all_digits);
128	    }
129	
130	    // Find index of lane with minimum popcount (for MRV heuristic)
131	    // Returns -1 if all lanes are filled (candidates == 0)
132	    inline int find_min_candidates(const Mask* candidates, int count, int& min_count)
133	    {
134	        min_count = 10;
135	        int best_idx = -1;
136	
137	        // Process 16 at a time
138	        int i = 0;
139	        for (; i + LANES <= count; i += LANES) {
140	            __m256i vec = load_candidates(&candidates[i]);
141	            __m256i popcnts = popcount_epi16(vec);
142	
143	            // Extract popcounts and find minimum among non-zero candidates
144	            alignas(32) unsigned char counts[LANES];
145	            _mm256_storeu_si256(reinterpret_cast<__m256i*>(counts), popcnts);
146	
147	            for (int j = 0; j < LANES; ++j) {
148	                int c = counts[j];
149	                if (c > 0 && c < min_count) {
150	                    min_count = c;
151	                    best_idx = i + j;
152	                    if (c <= 1) return best_idx;
153	                }
154	            }
155	        }
156	
157	        // Scalar tail
158	        for (; i < count; ++i) {
159	            if (candidates[i] != 0) {
160	                int c = popcount(candidates[i]);
161	                if (c < min_count) {
162	                    min_count = c;
163	                    best_idx = i;
164	                    if (c <= 1) return best_idx;
165	                }
166	            }
167	        }
168	
169	        return best_idx;
170	    }
171	}
172	#endif // SUDOKU_AVX2
