199	bool Sudoku::solve()
200	{
201		_solution = _grid;
202		std::fill(std::begin(_rows), std::end(_rows), 0);
203		std::fill(std::begin(_cols), std::end(_cols), 0);
204		std::fill(std::begin(_boxes), std::end(_boxes), 0);
205	
206		// Initialize masks from givens
207		for (int r = 0; r < N; ++r) {
208			for (int c = 0; c < N; ++c) {
209				int num = _solution[idx(r, c)];
210				if (num != 0) {
211					Mask m = DIGIT_MASK[num];
212					_rows[r] |= m;
213					_cols[c] |= m;
214					_boxes[BOX_OF[idx(r, c)]] |= m;
215				}
216			}
217		}
218	
219		// Initialize cell candidates
220		for (int r = 0; r < N; ++r) {
221			for (int c = 0; c < N; ++c) {
222				int i = idx(r, c);
223				if (_solution[i] == 0) {
224					_cell_candidates[i] = _getCandidates(r, c);
225				} else {
226					_cell_candidates[i] = 0;
227				}
228			}
229		}
230	
231		// Apply constraint propagation before search
232		_propagate();
233	
234		_solved = _solveRecursive();
235		return _solved;
236	}
