276	bool Sudoku::_isValid(int row, int col, int num) const
277	{
278		Mask m = DIGIT_MASK[num];
279		int b = BOX_OF[idx(row, col)];
280		return !(_rows[row] & m) && !(_cols[col] & m) && !(_boxes[b] & m);
281	}
