304	int Sudoku::_findBestCell() const
305	{
306	#if SUDOKU_AVX2
307		// Vectorized: find cell with minimum candidates among empty cells
308		// We need to consider only cells where _solution[i] == 0
309		// Create a mask of valid (empty) cells
310		int min_count = 10;
311		int best_idx = -1;
312	
313		// Process 16 cells at a time
314		for (int base = 0; base < 81; base += 16) {
315			int remaining = 81 - base;
316			int process = (remaining >= 16) ? 16 : remaining;
317	
318			// Load candidates for this chunk
319			alignas(32) Mask chunk_candidates[16];
320			alignas(32) uint16_t chunk_solution[16];
321	
322			for (int j = 0; j < process; ++j) {
323				chunk_candidates[j] = _cell_candidates[base + j];
324				chunk_solution[j] = _solution[base + j];
325			}
326			// Zero-pad the rest
327			for (int j = process; j < 16; ++j) {
328				chunk_candidates[j] = 0;
329				chunk_solution[j] = 1; // non-zero = filled
330			}
331	
332			__m256i vec_cand = SudokuAVX2::load_candidates(chunk_candidates);
333			__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(chunk_solution));
334	
335			// Mask out filled cells (set candidates to 0 where solution != 0)
336			__m256i sol_zero = _mm256_cmpeq_epi16(vec_sol, _mm256_setzero_si256());
337			vec_cand = _mm256_and_si256(vec_cand, sol_zero);
338	
339			// Compute popcounts
340			__m256i popcnts = SudokuAVX2::popcount_epi16(vec_cand);
341	
342			// Extract and find minimum
343			alignas(32) unsigned char counts[16];
344			_mm256_storeu_si256(reinterpret_cast<__m256i*>(counts), popcnts);
345	
346			for (int j = 0; j < process; ++j) {
347				int c = counts[j];
348				if (c > 0 && c < min_count) {
349					min_count = c;
350					best_idx = base + j;
351					if (c <= 1) return best_idx;
352				}
353			}
354		}
355	
356		return best_idx;
357	#else
358		int bestCell = -1;
359		int minCandidates = 10;
360	
361		for (int i = 0; i < 81; ++i) {
362			if (_solution[i] == 0) {
363				Mask candidates = _cell_candidates[i];
364				int count = _countBits(candidates);
365				if (count < minCandidates) {
366					minCandidates = count;
367					bestCell = i;
368					if (count <= 1) return bestCell;
369				}
370			}
371		}
372		return bestCell;
373	#endif
374	}
