376	// Constraint propagation techniques
377	bool Sudoku::_propagate()
378	{
379		bool progress = true;
380		while (progress) {
381			progress = false;
382			progress |= _nakedSingles();
383			progress |= _hiddenSingles();
384		}
385		return true;
386	}
