388	// Naked singles: cell with only 1 candidate
389	bool Sudoku::_nakedSingles()
390	{
391		bool progress = false;
392	
393	#if SUDOKU_AVX2
394		// Vectorized: find all naked singles in chunks of 16
395		for (int base = 0; base < 81; base += 16) {
396			int remaining = 81 - base;
397			int process = (remaining >= 16) ? 16 : remaining;
398	
399			alignas(32) Mask chunk_candidates[16];
400			alignas(32) uint16_t chunk_solution[16];
401	
402			for (int j = 0; j < process; ++j) {
403				chunk_candidates[j] = _cell_candidates[base + j];
404				chunk_solution[j] = _solution[base + j];
405			}
406			for (int j = process; j < 16; ++j) {
407				chunk_candidates[j] = 0;
408				chunk_solution[j] = 1;
409			}
410	
411			__m256i vec_cand = SudokuAVX2::load_candidates(chunk_candidates);
412			__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(chunk_solution));
413	
414			// Mask out filled cells
415			__m256i sol_zero = _mm256_cmpeq_epi16(vec_sol, _mm256_setzero_si256());
416			vec_cand = _mm256_and_si256(vec_cand, sol_zero);
417	
418			// Find naked singles: exactly 1 bit set
419			__m256i singles_mask = SudokuAVX2::naked_singles_mask(vec_cand);
420	
421			// Extract which lanes are naked singles
422			alignas(32) uint16_t mask_arr[16];
423			_mm256_storeu_si256(reinterpret_cast<__m256i*>(mask_arr), singles_mask);
424	
425			for (int j = 0; j < process; ++j) {
426				if (mask_arr[j]) {
427					int i = base + j;
428					Mask candidates = _cell_candidates[i];
429					int num = ctz(candidates);
430					int r = i / 9, c = i % 9;
431					_solution[i] = num;
432					Mask m = DIGIT_MASK[num];
433					_rows[r] |= m;
434					_cols[c] |= m;
435					_boxes[BOX_OF[i]] |= m;
436					_cell_candidates[i] = 0;
437					progress = true;
438				}
439			}
440		}
441	#else
442		for (int i = 0; i < 81; ++i) {
443			if (_solution[i] == 0) {
444				Mask candidates = _cell_candidates[i];
445				if (candidates && (candidates & (candidates - 1)) == 0) {
446					int num = ctz(candidates);
447					int r = i / 9, c = i % 9;
448					_solution[i] = num;
449					Mask m = DIGIT_MASK[num];
450					_rows[r] |= m;
451					_cols[c] |= m;
452					_boxes[BOX_OF[i]] |= m;
453					_cell_candidates[i] = 0;
454					progress = true;
455				}
456			}
457		}
458	#endif
459	
460		if (progress) {
461			for (int r = 0; r < N; ++r) {
462				for (int c = 0; c < N; ++c) {
463					_updateCandidates(r, c);
464				}
465			}
466		}
467		return progress;
468	}
