470	// Hidden singles: digit appears only once in a house
471	bool Sudoku::_hiddenSingles()
472	{
473		bool progress = false;
474	
475		// Check rows
476		for (int r = 0; r < N; ++r) {
477			for (int d = 1; d <= 9; ++d) {
478				Mask m = DIGIT_MASK[d];
479				if (_rows[r] & m) continue;
480				int count = 0, last_c = -1;
481				for (int c = 0; c < N; ++c) {
482					int i = idx(r, c);
483					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
484						count++;
485						last_c = c;
486					}
487				}
488				if (count == 1) {
489					int i = idx(r, last_c);
490					_solution[i] = d;
491					_rows[r] |= m;
492					_cols[last_c] |= m;
493					_boxes[BOX_OF[i]] |= m;
494					_cell_candidates[i] = 0;
495					progress = true;
496				}
497			}
498		}
499	
500		// Check columns
501		for (int c = 0; c < N; ++c) {
502			for (int d = 1; d <= 9; ++d) {
503				Mask m = DIGIT_MASK[d];
504				if (_cols[c] & m) continue;
505				int count = 0, last_r = -1;
506				for (int r = 0; r < N; ++r) {
507					int i = idx(r, c);
508					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
509						count++;
510						last_r = r;
511					}
512				}
513				if (count == 1) {
514					int i = idx(last_r, c);
515					_solution[i] = d;
516					_rows[last_r] |= m;
517					_cols[c] |= m;
518					_boxes[BOX_OF[i]] |= m;
519					_cell_candidates[i] = 0;
520					progress = true;
521				}
522			}
523		}
524	
525		// Check boxes
526		for (int b = 0; b < 9; ++b) {
527			for (int d = 1; d <= 9; ++d) {
528				Mask m = DIGIT_MASK[d];
529				if (_boxes[b] & m) continue;
530				int count = 0, last_cell = -1;
531				for (int i = 0; i < 81; ++i) {
532					if (BOX_OF[i] == b && _solution[i] == 0 && (_cell_candidates[i] & m)) {
533						count++;
534						last_cell = i;
535					}
536				}
537				if (count == 1) {
538					int r = last_cell / 9, c = last_cell % 9;
539					_solution[last_cell] = d;
540					_rows[r] |= m;
541					_cols[c] |= m;
542					_boxes[b] |= m;
543					_cell_candidates[last_cell] = 0;
544					progress = true;
545				}
546			}
547		}
548	
549		if (progress) {
550			for (int r = 0; r < N; ++r) {
551				for (int c = 0; c < N; ++c) {
552					_updateCandidates(r, c);
553				}
554			}
555		}
556		return progress;
557	}
