559	bool Sudoku::_solveRecursive()
560	{
561		int cell = _findBestCell();
562		if (cell == -1) return true; // solved
563	
564		int row = cell / 9;
565		int col = cell % 9;
566		Mask candidates = _cell_candidates[cell];
567		int b = BOX_OF[cell];
568	
569		// Try each candidate
570		while (candidates) {
571			Mask m = candidates & -candidates;
572			int num = ctz(m);
573			candidates &= candidates - 1;
574	
575			// Place digit
576			_solution[cell] = num;
577			_rows[row] |= m;
578			_cols[col] |= m;
579			_boxes[b] |= m;
580	
581			// Save and update affected candidates
582			Mask saved[81];
583			for (int i = 0; i < 81; ++i) saved[i] = _cell_candidates[i];
584	
585	#if SUDOKU_AVX2
586			// Vectorized: clear digit m from all candidates in chunks of 16
587			__m256i clear_mask = SudokuAVX2::broadcast_mask(~m);
588			for (int base = 0; base < 81; base += 16) {
589				int remaining = 81 - base;
590				int process = (remaining >= 16) ? 16 : remaining;
591	
592				__m256i vec_cand = SudokuAVX2::load_candidates(&_cell_candidates[base]);
593				__m256i vec_sol = _mm256_loadu_si256(reinterpret_cast<const __m256i*>(&_solution[base]));
594	
595				// Only clear for empty cells
596				__m256i sol_zero = _mm256_cmpeq_epi16(vec_sol, _mm256_setzero_si256());
597				__m256i cleared = _mm256_and_si256(vec_cand, clear_mask);
598				vec_cand = _mm256_blendv_epi8(vec_cand, cleared, sol_zero);
599	
600				SudokuAVX2::store_candidates(&_cell_candidates[base], vec_cand);
601			}
602	#else
603			for (int r = 0; r < N; ++r) {
604				for (int c = 0; c < N; ++c) {
605					int i = idx(r, c);
606					if (_solution[i] == 0 && (_cell_candidates[i] & m)) {
