#include <iostream>
#include <chrono>
#include <Sudoku.hpp>
#include <SudokuDLX.hpp>

using Grid = Sudoku::Grid;
using Clock = std::chrono::high_resolution_clock;

// Known hard puzzle (AI Escargot / "Easter Monster" variant) - defined in Sudoku.hpp as static constexpr

template<typename Solver>
void benchmark(const char* name, const Grid& puzzle, Grid& solution)
{
	auto start = Clock::now();
	bool solved = Solver::solve(puzzle, solution);
	auto end = Clock::now();
	auto duration = std::chrono::duration_cast<std::chrono::microseconds>(end - start);

	std::cout << name << ": ";
	if (solved)
	{
		std::cout << "SOLVED in " << duration.count() << " µs\n";
	}
	else
	{
		std::cout << "FAILED\n";
	}
}

